#!/usr/bin/env node
// json-output-doc: writes the field table of docs/json-output.md from the committed JSON Schema
// (schemas/crankpath-report.schema.json), between the two marker lines, so the reference can never
// drift from the schema: a test renders the table again and compares. Run it after a schema change:
//   node scripts/json-output-doc.mjs

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const START =
  "<!-- field table: generated by scripts/json-output-doc.mjs from the schema; do not edit by hand -->";
export const END = "<!-- end of the generated field table -->";

/** @param {Record<string, unknown>} root @param {Record<string, unknown>} node */
function deref(root, node) {
  let n = node;
  while (typeof n.$ref === "string") {
    const name = n.$ref.replace("#/$defs/", "");
    n = /** @type {Record<string, unknown>} */ (/** @type {Record<string, unknown>} */ (root.$defs)[name]);
  }
  return n;
}

/** @param {Record<string, unknown>} root @param {Record<string, unknown>} node @returns {string[]} */
function types(root, node) {
  const n = deref(root, node);
  if (Array.isArray(n.anyOf)) return [...new Set(n.anyOf.flatMap((o) => types(root, o)))].sort();
  if (n.const !== undefined)
    return [n.const === null ? "null" : typeof n.const === "number" ? "integer" : typeof n.const];
  if (n.type === undefined) return ["any"];
  return (Array.isArray(n.type) ? [...n.type] : [String(n.type)]).sort();
}

/** @param {Record<string, unknown>} root @param {Record<string, unknown>} node @returns {unknown[] | undefined} */
function words(root, node) {
  const n = deref(root, node);
  if (Array.isArray(n.enum)) return n.enum;
  if (Array.isArray(n.anyOf)) {
    for (const o of n.anyOf) {
      const w = words(root, o);
      if (w !== undefined) return w;
    }
  }
  if (n.const !== undefined && typeof n.const === "string") return [n.const];
  return undefined;
}

/** @param {string} text */
function cell(text) {
  return text.replace(/\|/g, "\\|").replace(/\n/g, " ");
}

/**
 * The table rows: one per field path (`cycles[].edges[].from`), its JSON types and its meaning (the
 * schema's description, with the allowed words when the field is a word list).
 * @param {Record<string, unknown>} schema
 * @returns {string[]}
 */
export function fieldRows(schema) {
  /** @type {[string, string][]} */
  const rows = [];
  /** @param {Record<string, unknown>} node @param {string} at @param {string} description */
  const add = (node, at, description) => {
    const w = words(schema, node);
    const list =
      w === undefined ? "" : ` Words: ${w.map((x) => (x === null ? "null" : `\`${String(x)}\``)).join(", ")}.`;
    rows.push([at, `| \`${at}\` | ${types(schema, node).join(" or ")} | ${cell(description)}${cell(list)} |`]);
  };
  /** @param {Record<string, unknown>} node @param {string} at */
  const walk = (node, at) => {
    const n = deref(schema, node);
    const options = Array.isArray(n.anyOf) ? n.anyOf.map((o) => deref(schema, o)) : [n];
    for (const o of options) {
      if (o.properties !== undefined) {
        for (const [k, p] of Object.entries(/** @type {Record<string, Record<string, unknown>>} */ (o.properties))) {
          const here = at === "" ? k : `${at}.${k}`;
          const d = String(p.description ?? deref(schema, p).description ?? "");
          add(p, here, d);
          walk(p, here);
        }
      }
      if (o.items !== undefined) {
        const items = /** @type {Record<string, unknown>} */ (o.items);
        add(items, `${at}[]`, String(items.description ?? deref(schema, items).description ?? "one entry"));
        walk(items, `${at}[]`);
      }
    }
  };
  walk(schema, "");
  return rows.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([, row]) => row);
}

/** The generated section, marker lines included. @param {Record<string, unknown>} schema */
export function fieldTable(schema) {
  return [START, "", "| Field | Type | Meaning |", "|---|---|---|", ...fieldRows(schema), "", END].join("\n");
}

/** The doc with its generated section replaced. @param {string} doc @param {Record<string, unknown>} schema */
export function withTable(doc, schema) {
  const a = doc.indexOf(START);
  const b = doc.indexOf(END);
  if (a < 0 || b < a) throw new Error("docs/json-output.md: the field table markers are missing");
  return `${doc.slice(0, a)}${fieldTable(schema)}${doc.slice(b + END.length)}`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
  const schema = JSON.parse(fs.readFileSync(path.join(root, "schemas", "crankpath-report.schema.json"), "utf8"));
  const docPath = path.join(root, "docs", "json-output.md");
  fs.writeFileSync(docPath, withTable(fs.readFileSync(docPath, "utf8"), schema));
}
